   [key: string]: any; // Allow other response fields
 }

+export const BING_RETIRED_MESSAGE =
+  'The Bing Search API was retired by Microsoft on 2025-08-11. Set SEARCH_API_URL to a Bing-compatible endpoint, or use another SEARCH_PROVIDER (tavily, google, exa, searxng, duckduckgo, ...).';
+
 export async function bingSearch(options: ISearchRequestOptions, signal?: AbortSignal): Promise<ISearchResponse> {
-  const { query, limit = 10, safeSearch = 0, page = 1, apiUrl = 'https://api.bing.microsoft.com/v7.0/search', apiKey, language } = options;
+  const { query, limit = 10, safeSearch = 0, page = 1, apiUrl, apiKey, language } = options;

   if (!query?.trim()) {
     throw new Error('Query cannot be empty');
   }

+  // Bing Search APIs (api.bing.microsoft.com) were retired on 2025-08-11.
+  // Only a user-supplied Bing-compatible endpoint (SEARCH_API_URL) can still work.
+  if (!apiUrl) {
+    throw new Error(BING_RETIRED_MESSAGE);
+  }
+
   if (!apiKey) {
     throw new Error('Bing API key is required');
   }
diff --git a/test/bing.test.ts b/test/bing.test.ts
new file mode 100644
index 0000000..a61ae24
--- /dev/null
+++ b/test/bing.test.ts
@@ -0,0 +1,21 @@
+import { afterEach, describe, expect, it, vi } from 'vitest';
+import { bingSearch } from '../src/search/bing.js';
+
+describe('bingSearch (retired API)', () => {
+  afterEach(() => vi.unstubAllGlobals());
+
+  it('fails with a clear error and no request when no apiUrl is set', async () => {
+    const fetchMock = vi.fn();
+    vi.stubGlobal('fetch', fetchMock);
+    await expect(bingSearch({ query: 'x', apiKey: 'k' })).rejects.toThrow(/retired/);
+    expect(fetchMock).not.toHaveBeenCalled();
+  });
+
+  it('still calls a custom apiUrl', async () => {
+    const fetchMock = vi.fn(async () => ({ ok: true, json: async () => ({ webPages: { value: [] } }) }));
+    vi.stubGlobal('fetch', fetchMock);
+    const res = await bingSearch({ query: 'x', apiKey: 'k', apiUrl: 'https://proxy.example/search' });
+    expect(res.success).toBe(true);
+    expect(String((fetchMock.mock.calls[0] as unknown[])[0])).toContain('https://proxy.example/search?');
+  });
+});
